"""Offline transparent native results, claim diagnostics and closed-balance graphs."""
from pathlib import Path
import gzip,html,json
from datetime import datetime
R=Path(__file__).resolve().parent
def load(p):return json.loads(p.read_text(encoding='utf-8'))
def f(v,n=2):return '—' if v is None else f'{v:.{n}f}'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def graph(z):
 trades=json.loads(gzip.decompress((R/'native'/z['tag']/'trades.json.gz').read_bytes()));points=[(datetime(2025,10,3).timestamp(),10000)];balance=10000
 for t in trades:balance+=t['net_profit'];points.append((datetime.fromisoformat(t['close_time']).timestamp(),balance))
 points.append((datetime(2026,10,3).timestamp(),balance));low=min(y for _,y in points);high=max(y for _,y in points);span=max(high-low,1);low-=span*.08;high+=span*.08;start=points[0][0];end=points[-1][0]
 xy=[(35+(x-start)/(end-start)*690,175-(y-low)/(high-low)*145) for x,y in points];d='M'+f'{xy[0][0]:.2f},{xy[0][1]:.2f}'+''.join(f' H{x:.2f} V{y:.2f}' for x,y in xy[1:]);color='#ff9292' if balance<10000 else '#75f8c5'
 return f'<svg viewBox="0 0 760 220" role="img" aria-label="{z["timeframe"]} closed balance, not floating equity"><text x="35" y="20" fill="#b9cccc">${high:,.0f}</text><text x="35" y="203" fill="#b9cccc">${low:,.0f} · 3 Oct 2025 → 3 Oct 2026</text><path d="{d}" fill="none" stroke="{color}" stroke-width="2"/></svg>'
def main():
 results=load(R/'SUMMARY.json');assert len(results)==6;claim=load(R/'CLAIM_AUDIT.json');verification=load(R/'VERIFICATION.json');assert len(verification['cases'])==7
 headers=['Timeframe','Version','Net return','Net PF','Win rate','Equity DD','Trades','/month','/weekday','W / L streak','Sharpe¹'];rows=[];md=['# Gold candle lifecycle — raw one-year test','','Verdict: none of the three literal raw versions was profitable after costs. H4 was nearly flat, but its floating-equity drawdown was large. This tests the frozen interpretation, not an exact undisclosed video strategy.','','Period: 3 Oct 2025–2 Oct 2026 inclusive. XAUUSD Exness MT5 broker-server candles, 10000 USD separate accounts, 1% equity-risk TARGET, lots rounded up/minimum lot. Actual planned risk can exceed the target. Native Model 4, 150ms delay, broker spread/commission/swap. 75% real-tick coverage; real ticks start 1 Jan 2026.','','## Exact implementation','','Bearish only: previous parent candle red; new candle trades at least one tick above its open in first half; a completed M1 candle in second half closes below that open, current bid also below. Sell once. Stop above the maximum high KNOWN at entry plus current spread and two ticks, widened for broker rules. No TP/trailing; exit on first tradable quote at/after parent-end. These entry-confirmation/stop/exit details are our assumptions. No future final high or final close was used to enter.','','Control: sell after previous red at first completed M1 in second half, without first-half-up / bearish-flip filters; same sizing, observed-high stop and time exit. It is not matched random.','','## Native results','','| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']
 for z in results:
  s=z['stats'];row=[z['timeframe'],'Control' if z['control'] else 'Video interpretation',f(s['return_pct'])+'%',f(s['pf'],3),f(s['win_pct'],1)+'%',f(s['equity_dd_pct'])+'%',s['trades'],f(s['trades_month']),f(s['trades_weekday'],3),f'{s["max_win_streak"]} / {s["max_loss_streak"]}',f(s['sharpe'])];rows.append(row);md.append('| '+' | '.join(map(str,row))+' |')
 diagnostics=[];diagheads=['TF','Candles²','Previous-red sample','Next red after red','High first half after red','High near midpoint³','Final-red high first half⁴']
 md+=['','## Candle claims (descriptive, not entry rules)','','| '+' | '.join(diagheads)+' |','|'+'|'.join(['---']*len(diagheads))+'|']
 for tf,c in claim['timeframes'].items():
  row=[tf,c['candles'],c['prior_red_candles'],f(c['next_red_after_red_pct'],1)+'%',f(c['prior_red_high_first_half_pct'],1)+'%',f(c['high_in_middle_40_60_pct'],1)+'%',f(c['final_red_high_first_half_pct'],1)+'%'];diagnostics.append(row);md.append('| '+' | '.join(map(str,row))+' |')
 md+=['','Previous-red continuation was about 49%, with bootstrap intervals covering no improvement over other prior candles. A high in the first half was only about 53–54% on H1/H4 and 45% on D1 overall. Highs specifically near halfway were uncommon. The much higher first-half-high rate among candles that FINALLY close red (75–85%) is retrospective conditioning: final colour was unknown at entry.','','² Timing diagnostics require quotes in BOTH halves and a prior native candle; exclude truncated session/Sunday candles. Native trading uses the real broker series; its prior D1 may be a short Sunday candle. No New York day anchoring assumed.','³ High timestamp between 40% and 60% of nominal candle duration, not a traded filter.','⁴ Conditioned on future final colour for descriptive analysis only. Tied extrema first/last occurrence tested separately; M1 resolution, not exact tick times.','','## Execution limitations','','H1 time closes repeatedly encountered historical broker market-closed states (10018); rejected entries were not counted as trades, and exits retried at subsequent quotes. Invalid stops (10016) and insufficient margin (10019) are reported as MISSED entries, never repaired into successful fills. Initial verifier-only classification amendments and original failed-validation logs are retained; strategy source and parameters never changed.','','H1 control finished with negative simulated capital (−107.20% return). That is a failed risk scenario in the MT5 simulation, not an investable strategy or a claim about broker negative-balance protection. Broker minimum lots and gap/quote execution can violate the nominal 1% target.','','| TF / version | Entry attempts | Fills | Market-closed entries | Invalid-stop entries | No-margin entries | Close retries (closed) | Late exits >60s | Max delay hours | Max planned risk / target |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 execution=[]
 for z in results:
  a=z['audit'];row=[z['tag'],a['entry_attempts'],a['entries'],a['market_closed_entries'],a['invalid_stop_entries'],a['insufficient_funds_entries'],a['market_closed_exit_retries'],a['late_exits_over_60s'],f(a['max_exit_delay_hours']),f(a['max_actual_vs_selected_risk_ratio'])+'×'];execution.append(row);md.append('| '+' | '.join(map(str,row))+' |')
 md+=['','¹ Calendar-day closed-balance return Sharpe, zero risk-free rate, includes zero days; not floating-equity Sharpe. Control Sharpe is not meaningful as a viable performance measure after capital failure.','',f'Independent verification: {verification["attempts_checked"]} entry attempts and {verification["fills_checked"]} fills (including smoke) reconstructed from native M1 and parent data. All source and binary hashes unchanged. Native parent OHLC matches M1 aggregation; no future price leakage. Six unique raw strategy/timeframe configurations; two identical-input H1 reruns after verifier-only corrections, plus one technical smoke test and no-order exporter.','', 'No optimisation, no live/BAT changes, no FTMO promotion, no full 3-/5-year pipeline gate. This is one-year exploratory evidence, not proof of future results.']
 (R/'REPORT.md').write_text('\n'.join(md),encoding='utf-8')
 charts=''.join('<section><h2>'+z['timeframe']+' · video interpretation</h2><p>Closed balance only, excluding floating P&amp;L. Native floating-equity drawdown is reported in the table.</p>'+graph(z)+'</section>' for z in results if not z['control'])
 doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Calyx · Gold candle lifecycle</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#081511;color:#e8f7f1;font:15px/1.65 system-ui}main{max-width:1450px;margin:auto;padding:42px 24px}h1{font-size:42px;line-height:1.15}h2{color:#75f8c5}p{color:#aec7c7}.brand{color:#75f8c5;font-size:12px;letter-spacing:3px}.warning{background:#2b251b;border:1px solid #a08a4c;border-radius:14px;padding:18px}.bad{color:#ff9292}section{margin:26px 0;padding:24px;border-radius:18px;border:1px solid #29463b;background:#0d1e18}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:11px 9px;border-bottom:1px solid #29463b;text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}svg{background:#091813;border-radius:12px;width:100%;max-width:1000px}footer{padding:25px;color:#a6c1bd}</style><main><div class="brand">CALYX · RAW RESEARCH · OFFLINE</div><h1>Gold candle lifecycle.<br><span class="bad">No profitable raw version.</span></h1><p>3 Oct 2025–2 Oct 2026 · H1 / H4 / daily · 10000 USD each · 1% equity-risk target · native Model 4 · 150ms delay.</p><div class="warning">Exploratory evidence, not a forecast. The video omits exact entries/stops/exits; this tests our frozen interpretation. Only 75% real ticks. Broker lots rounded up can exceed 1% target risk. No live trading changes.</div><section><h2>What was actually traded</h2><p>Previous red candle → first-half upward excursion → completed second-half M1 close below the current candle open → market sell. One attempt per candle. Stop uses only highs already observed, plus spread/two ticks and broker requirements. No TP/trailing; close at parent-end’s first tradable quote. Bearish only, as illustrated; no added bullish mirror or optimised filters.</p><p>Control: simple previous-red continuation sell after halfway without the extra excursion/flip conditions, with the same causal stop/time exit. Not matched random.</p></section><section><h2>All six native results</h2>'''+table(headers,rows)+'''<p>PF/win rate use net P&amp;L, including commission and swap. DD is native floating-equity peak-to-trough drawdown. Trades are successful fills, not rejected attempts. Separate accounts, not a combined portfolio. Sharpe¹ uses calendar-day closed-balance returns.</p></section><section><h2>Does the candle claim hold?</h2>'''+table(diagheads,diagnostics)+'''<p>Previous-red continuation is about 49%—not a high-probability bearish prediction. In retrospect, red candles often made their high early, but final colour was unknown when the trade had to be entered. Knowing a final high is in the first half would be lookahead.</p><p>² Quotes in both halves required for timing diagnostics; short session/Sunday candles excluded from these descriptive ratios, not removed from the native prior-candle series. ³ “Near midpoint” means 40–60% of nominal duration, not a strategy filter. ⁴ Future final-red colour, used descriptively only. Minute timestamps, tied high/low sensitivity checked. Broker-server day, not NY daily close.</p></section>'''+charts+'<section><h2>Execution and risk audit</h2>'+table(['Case','Attempts','Fills','Closed entries','Invalid stops','No margin','Close retries','Late >60s','Max delay h','Risk/target max'],execution)+f'''<p>Historical quotes sometimes existed while MT5 marked trading closed. Return codes 10018 / 10016 / 10019 are rejected orders, not profitable fills. Close retries and delays are retained. Strategy source was unchanged; technical verifier amendments are recorded separately.</p><p class="bad">H1 control depleted the simulated account and ended below zero. Its −107.20% return is a risk failure, not viable performance or a claim about broker negative-balance protection. Lot rounding and execution gaps can exceed selected risk.</p></section><footer><h2>Verification and boundaries</h2><p>{verification["attempts_checked"]} attempted entries and {verification["fills_checked"]} fills reconstructed against native parent/M1 history, including smoke. Native parent OHLC matches M1 aggregation; final extrema never entered into signals. 11 unit tests; both EAs compile with 0 errors and 0 warnings.</p><p>All six raw configurations shown; two identical-input H1 retries were verifier-only corrections, not optimisation. 75% real ticks, commencing 1 Jan 2026; earlier segment generated. No full 3-/5-year pipeline gate, holdout or portfolio/FTMO simulation. Live terminals and installers untouched.</p></footer></main></html>'''
 (R/'Results.html').write_text(doc,encoding='utf-8');print('Full native results, claim diagnostics, risk audit and three graphs saved.')
if __name__=='__main__':main()
